t3template.addControl({ id: 'minMs', label: 'Min latency', type: 'slider', min: 0, max: 1000, step: 50, default: 0, panel: 'Latency', onChange(v, t) { const q = t.getValues().query.replace(/\s*latency_ms:>=\d+/g, '').trim(); t.setValues({ query: v > 0 ? `${q} latency_ms:>=${v}`.trim() : q }, `Min latency ${v} ms`); } });
t3template.addToolbarButton('Slow Requests', (t) => t.setValues({ query: 'latency_ms:>=1000' }, 'Slow Requests'), { shortcut: 'shift+r' });
t3template.addPreset('Incident 14:21', { timeRange: { from: '2026-10-13T14:21:00.000Z', to: '2026-10-13T14:24:30.000Z' }, query: 'status:504' });
t3template.applyPreset('Incident 14:21');
